import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.CDU0sSpB.js";const _=JSON.parse('{"title":"第一阶段 · 最小完整 MVP","description":"交付一个以 15 个跨行业真实任务为基线、至少通过 10 个的最小完整产品。","frontmatter":{"title":"第一阶段 · 最小完整 MVP","description":"交付一个以 15 个跨行业真实任务为基线、至少通过 10 个的最小完整产品。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-1.md","filePath":"delivery/stage-1.md","lastUpdated":1794015952000}'),l={name:"delivery/stage-1.md"};function h(i,t,o,s,n,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="第一阶段-·-最小完整-mvp" tabindex="-1">第一阶段 · 最小完整 MVP <a class="header-anchor" href="#第一阶段-·-最小完整-mvp" aria-label="Permalink to &quot;第一阶段 · 最小完整 MVP&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><p>阶段一已验收完成：15 个跨行业真实任务实际运行 15 个、通过 13 个，达到 10/15 的硬门槛。T07 因测试文件未提交而失败，T08 的评论动作仍待批准，两项都保留为未完成边界。验收过程见<a href="/hearth-os/log/day-04.html">Day04 开发日志</a>。</p><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>第一阶段交付一个可以在真实浏览器里每天使用的最小完整产品。它以 15 个跨行业真实任务为基线，至少要通过其中 10 个，并完整走完“创建任务—执行—审批—查看产物—失败恢复”的路径。这个阶段不追求覆盖所有工作，但必须证明同一套任务、审批、产物和恢复机制能处理多个任务族。</p><p>本阶段分为四个小阶段：</p><table tabindex="0"><thead><tr><th>小阶段</th><th>目标</th></tr></thead><tbody><tr><td><a href="/hearth-os/delivery/stage-1/1-1.html">1.1 明确首个场景与真实任务</a></td><td>确定首位用户、15 个真实任务、非目标和验收标准。</td></tr><tr><td><a href="/hearth-os/delivery/stage-1/1-2.html">1.2 做出完整体验原型</a></td><td>用可点击原型走通任务、审批、产物和恢复。</td></tr><tr><td><a href="/hearth-os/delivery/stage-1/1-3.html">1.3 打通最小任务闭环</a></td><td>让任务能真实执行、审批、产出结果并在失败后恢复。</td></tr><tr><td><a href="/hearth-os/delivery/stage-1/1-4.html">1.4 用真实任务验收 MVP</a></td><td>让首位用户不依赖开发者也能独立使用。</td></tr></tbody></table><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>先确定首位用户和 15 个跨行业真实任务，并用真实输入确定验收标准。</li><li>用可点击原型把完整路径和所有关键状态走一遍。</li><li>打通真实任务闭环，包括执行、审批、产物和失败恢复。</li><li>让首位用户连续使用一周，用至少 10/15 个任务验收 MVP。</li></ol>',9)])])}const m=a(l,[["render",h]]);export{_ as __pageData,m as default};
